spite_fault_write(line);
#ifdef SPITE_FAULT_TRACE
int64_t kept = spite_assert_total < 32 ? spite_assert_total : 32;
for (int64_t index = spite_assert_total - kept; index < spite_assert_total; index = index + 1) {
spite_fault_add(line, spite_assert_trace[index % 32]);
if (line->length > 0 && line->bytes[line->length - 1] == '\n') line->length = line->length - 1;
spite_fault_write(line);
}
if (spite_assert_total > 32) { spite_fault_add(line, "spite.assert\tearlier="); spite_fault_add_number(line, (uint64_t)(spite_assert_total - 32), 10); spite_fault_write(line); }
#endif
